<script setup>
import PublicLayout from '../../../Layouts/PublicLayout.vue';
import AdminQuickLinks from '../../../Components/AdminQuickLinks.vue';
import { useForm, router } from '@inertiajs/vue3';
import { ref } from 'vue';
const props = defineProps({ spotlights: { type: Array, default: () => [] }, members: { type: Array, default: () => [] } });
const form = useForm({ alumni_profile_id: '', headline: '', writeup: '', sort_order: 0, is_active: true });
const editing = ref({});
const submit = () => form.post('/admin/spotlights', { onSuccess: () => form.reset() });
const save = (item) => router.patch(`/admin/spotlights/${item.id}`, item);
const remove = (item) => { if (confirm(`Remove ${item.alumni_profile?.first_name || 'this member'} from spotlight?`)) router.delete(`/admin/spotlights/${item.id}`); };
</script>
<template><PublicLayout><section class="bg-[#00351F] py-5"><AdminQuickLinks /></section><div class="mx-auto max-w-6xl px-5 py-8"><p class="text-xs font-bold uppercase tracking-widest text-green-700">Homepage and Alumni page</p><h1 class="mt-2 text-3xl font-extrabold text-gray-900">Alumni Spotlight</h1><p class="mt-2 text-sm text-gray-600">Select approved members, add a short profile write-up and control the display order. Active spotlights appear on the homepage and above Graduation Sets on the Alumni page.</p>
<div class="mt-8 rounded-2xl border bg-white p-6"><h2 class="text-lg font-bold">Add a member to the spotlight</h2><form @submit.prevent="submit" class="mt-5 grid gap-4 md:grid-cols-2"><label class="text-sm font-semibold">Member<select v-model="form.alumni_profile_id" required class="mt-1 w-full rounded-lg border-gray-300"><option value="">Select approved member</option><option v-for="m in members" :key="m.id" :value="m.id">{{ m.first_name }} {{ m.last_name }} — {{ m.graduation_set?.name || m.class_set || 'Set not assigned' }}</option></select></label><label class="text-sm font-semibold">Short heading (optional)<input v-model="form.headline" maxlength="160" class="mt-1 w-full rounded-lg border-gray-300" placeholder="e.g. Building impact through education" /></label><label class="text-sm font-semibold md:col-span-2">Spotlight write-up<textarea v-model="form.writeup" required maxlength="1500" rows="4" class="mt-1 w-full rounded-lg border-gray-300" placeholder="A short introduction about the alumnus, career, contribution or achievement..."></textarea></label><label class="text-sm font-semibold">Display order<input v-model="form.sort_order" type="number" min="0" class="mt-1 w-full rounded-lg border-gray-300" /></label><label class="flex items-center gap-2 text-sm"><input v-model="form.is_active" type="checkbox" class="rounded border-gray-300 text-green-700" /> Active and visible</label><div class="md:col-span-2"><button :disabled="form.processing" class="rounded-lg bg-[#006B3C] px-5 py-3 text-sm font-bold text-white disabled:opacity-50">Add Spotlight</button><p v-if="form.errors.alumni_profile_id" class="mt-2 text-sm text-red-600">{{ form.errors.alumni_profile_id }}</p><p v-if="form.errors.writeup" class="mt-2 text-sm text-red-600">{{ form.errors.writeup }}</p></div></form></div>
<div class="mt-8"><h2 class="text-lg font-bold">Current spotlights</h2><div v-if="!spotlights.length" class="mt-3 rounded-xl border border-dashed p-8 text-center text-sm text-gray-500">No members selected yet.</div><div v-for="item in spotlights" :key="item.id" class="mt-4 rounded-xl border bg-white p-5"><div class="flex flex-wrap items-start justify-between gap-3"><div><h3 class="font-bold">{{ item.alumni_profile?.first_name }} {{ item.alumni_profile?.last_name }}</h3><p class="text-xs text-gray-500">{{ item.alumni_profile?.graduation_set?.name || item.alumni_profile?.class_set }}</p></div><button @click="remove(item)" class="text-sm font-semibold text-red-600">Remove</button></div><div class="mt-4 grid gap-3 md:grid-cols-2"><label class="text-xs font-semibold">Heading<input v-model="item.headline" class="mt-1 w-full rounded-lg border-gray-300 text-sm" /></label><label class="text-xs font-semibold">Display order<input v-model.number="item.sort_order" type="number" min="0" class="mt-1 w-full rounded-lg border-gray-300 text-sm" /></label><label class="text-xs font-semibold md:col-span-2">Write-up<textarea v-model="item.writeup" rows="3" class="mt-1 w-full rounded-lg border-gray-300 text-sm"></textarea></label><label class="flex items-center gap-2 text-sm"><input v-model="item.is_active" type="checkbox" /> Active</label><div class="md:col-span-2"><button @click="save(item)" class="rounded-lg border border-green-700 px-4 py-2 text-sm font-bold text-green-800">Save changes</button></div></div></div></div></div></PublicLayout></template>
